mapper.sql:
WHERE d.delete_yn = 'N'
AND d.use_yn = #{search.useYn}
AND d.parent_department_id IS NULL
AND d.parent_department_id = #{search.parentDepartmentId}
AND (d.department_code LIKE CONCAT('%', #{search.keyword}, '%') OR d.department_name LIKE CONCAT('%', #{search.keyword}, '%') OR d.description LIKE CONCAT('%', #{search.keyword}, '%'))

mapper.select:
SELECT COUNT(1)
  FROM tb_department
 WHERE department_code = #{departmentCode}
   AND delete_yn       = 'N'

  AND department_id <> #{excludeDepartmentId}
